17	 * Validate and sanitize config file path to prevent path traversal
18	 */
19	function validateConfigPath(inputPath: string, cwd: string = process.cwd()): string {
20	  // Normalize the path to resolve .. and .
21	  const normalizedPath = normalize(inputPath);
22	
23	  // Block absolute paths and paths with traversal
24	  if (normalizedPath.startsWith('/') || normalizedPath.startsWith('\\')) {
25	    throw new Error('Absolute paths are not allowed for config files');
26	  }
27	  if (normalizedPath.includes('..')) {
28	    throw new Error('Path traversal (..) is not allowed');
29	  }
30	
31	  // Only allow .json and .config.* files
32	  const allowedExtensions = ['.json', '.config.json', '.config.js', '.config.ts'];
33	  const hasAllowedExt = allowedExtensions.some(ext => normalizedPath.endsWith(ext));
34	  if (!hasAllowedExt) {
35	    throw new Error('Only .json and .config.* file extensions are allowed');
36	  }
37	
38	  // Resolve to absolute path within cwd
39	  const resolvedPath = resolve(cwd, normalizedPath);
40	
41	  // Ensure the resolved path is within cwd
42	  if (!resolvedPath.startsWith(cwd)) {
43	    throw new Error('Config path must be within current working directory');
44	  }
45	
46	  return resolvedPath;
47	}
